import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.piE7uVCg.js";const p=JSON.parse('{"title":"Previdia","description":"","frontmatter":{},"headers":[],"relativePath":"securite/incendie/previdia.md","filePath":"securite/incendie/previdia.md"}'),l={name:"securite/incendie/previdia.md"};function d(s,e,n,o,u,f){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="previdia" tabindex="-1"><a href="./readme.html">Previdia</a> <a class="header-anchor" href="#previdia" aria-label="Permalink to &quot;[Previdia](readme.md)&quot;">​</a></h1><h2 id="codes-utilisateurs" tabindex="-1">Codes utilisateurs <a class="header-anchor" href="#codes-utilisateurs" aria-label="Permalink to &quot;Codes utilisateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Niveau</th><th style="text-align:left;">Code</th></tr></thead><tbody><tr><td style="text-align:left;">Utilisateur</td><td style="text-align:left;">00001</td></tr><tr><td style="text-align:left;">Super Utilisateur</td><td style="text-align:left;">00002</td></tr><tr><td style="text-align:left;">Code d&#39;entretien</td><td style="text-align:left;">00003</td></tr><tr><td style="text-align:left;">Installation</td><td style="text-align:left;">00004</td></tr></tbody></table><h2 id="identifiant-previdia" tabindex="-1">Identifiant Previdia <a class="header-anchor" href="#identifiant-previdia" aria-label="Permalink to &quot;Identifiant Previdia&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Utilisateur</th><th style="text-align:left;">Identifiant</th><th style="text-align:left;">Mot de passe</th></tr></thead><tbody><tr><td style="text-align:left;">Utilisateur</td><td style="text-align:left;">User</td><td style="text-align:left;">pass</td></tr><tr><td style="text-align:left;">Super Utilisateur</td><td style="text-align:left;">UserADV</td><td style="text-align:left;">passadv</td></tr><tr><td style="text-align:left;">Programmateur</td><td style="text-align:left;">Admin</td><td style="text-align:left;">admin</td></tr></tbody></table><h2 id="site-officiel" tabindex="-1">Site officiel <a class="header-anchor" href="#site-officiel" aria-label="Permalink to &quot;Site officiel&quot;">​</a></h2><p><a href="https://www.inim.it/fr/produits/fire-safety/" target="_blank" rel="noreferrer">Inim</a></p><h2 id="lecture-de-boucle" tabindex="-1">Lecture de boucle <a class="header-anchor" href="#lecture-de-boucle" aria-label="Permalink to &quot;Lecture de boucle&quot;">​</a></h2><p>Sur une centrale Previdia Compact, les fonctions Read Address et Enroll ont des rôles différents :</p><p>Read Address (Lire l&#39;adresse) : la centrale interroge un détecteur ou un module déjà adressé pour lire son adresse actuelle, son type, son numéro de série et d&#39;autres informations. Cette opération ne modifie rien sur le dispositif. Elle est utile pour vérifier ou identifier un équipement existant. Enroll (Enrôler / Enregistrer) : la centrale ajoute un nouveau détecteur ou module dans sa configuration. Elle détecte le dispositif présent sur la boucle et l&#39;enregistre dans la base de données de la centrale afin qu&#39;il soit supervisé et utilisé par le système.</p><p>En pratique :</p><p>Vous remplacez un détecteur déjà configuré et vous voulez simplement vérifier son adresse → Read Address. Vous installez un nouveau détecteur ou un nouveau module qui n&#39;est pas encore connu de la centrale → Enroll.</p>',12)])])}const h=t(l,[["render",d]]);export{p as __pageData,h as default};
